const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var lakeUrmia = ee.Geometry.Polygon([
    [[45.00, 38.00], [45.50, 38.00], [45.50, 37.25], [45.00, 37.25]]
  ]);
  var aprilDate = ee.Date('2016-04-23');
  var julyDate = ee.Date('2016-07-18');

  // 2. Data Acquisition - Landsat 8 SR
  function getL8Image(date) {
    var start = date.advance(-15, 'day');
    var end = date.advance(15, 'day');

    var l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(start, end)
      .filterBounds(lakeUrmia)
      .filter(ee.Filter.lt('CLOUD_COVER', 30))
      .sort('CLOUD_COVER')
      .first();

    return ee.Algorithms.If({
      condition: ee.Image(l8).bandNames().size().gt(0),
      trueCase: ee.Image(l8),
      falseCase: null
    });
  }

  var imgApr = getL8Image(aprilDate);
  var imgJul = getL8Image(julyDate);

  // Check if images exist
  var aprExists = ee.Image(imgApr).bandNames().size().gt(0).getInfo();
  var julExists = ee.Image(imgJul).bandNames().size().gt(0).getInfo();

  if (!aprExists || !julExists) {
    console.log(`April 23 images: ${aprExists ? 'Found' : 'None'}`);
    console.log(`July 18 images: ${julExists ? 'Found' : 'None'}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // Process both images
  function processImage(img) {
    // Scale to reflectance and mask clouds (using QA_PIXEL)
    var qa = img.select('QA_PIXEL');
    var cloudMask = qa.bitwiseAnd(1 << 3).eq(0)  // Cloud shadow
                     .and(qa.bitwiseAnd(1 << 4).eq(0))  // Cloud
                     .and(qa.bitwiseAnd(1 << 1).eq(0)); // Dilated cloud

    // Calculate redness: Red / (Red + Green + Blue)
    var red = img.select('SR_B4').multiply(0.0000275).add(-0.2);
    var green = img.select('SR_B3').multiply(0.0000275).add(-0.2);
    var blue = img.select('SR_B2').multiply(0.0000275).add(-0.2);

    var redness = red.divide(red.add(green).add(blue));

    // Mask clouds and clip
    return redness.updateMask(cloudMask).clip(lakeUrmia);
  }

  var redApr = processImage(imgApr);
  var redJul = processImage(imgJul);

  // Count valid pixels
  var countApr = redApr.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeUrmia,
    scale: 1000,
    maxPixels: 1e9
  }).get('SR_B4').getInfo();

  var countJul = redJul.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeUrmia,
    scale: 1000,
    maxPixels: 1e9
  }).get('SR_B4').getInfo();

  console.log(`April valid pixels: ${countApr}`);
  console.log(`July valid pixels: ${countJul}`);

  if (countApr === 0 || countJul === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean redness
  var meanApr = redApr.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: lakeUrmia,
    scale: 1000,
    maxPixels: 1e9
  }).get('SR_B4').getInfo();

  var meanJul = redJul.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: lakeUrmia,
    scale: 1000,
    maxPixels: 1e9
  }).get('SR_B4').getInfo();

  console.log(`April redness: ${meanApr ? meanApr.toFixed(4) : 'null'}`);
  console.log(`July redness: ${meanJul ? meanJul.toFixed(4) : 'null'}`);

  // Validation & Final Answer
  if (meanApr === null || meanJul === null || 
      meanApr > 1 || meanJul > 1 || 
      meanApr < 0 || meanJul < 0) {
    console.log("<answer>C3</answer>");
  } else if (meanJul < meanApr) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
